cd /home/runner/work/PlayGround/PlayGround && cat >> verde-v3.css <<'EOF'

/* ---- presupuestos indoor/outdoor + mercado ---- */
.budget-mode-row{display:flex;gap:6px;margin:10px 0 12px}
.budget-mode{flex:1;height:36px;border-radius:10px;border:1px solid var(--line);background:rgba(8,10,6,.45);color:#b7c2a6;font:700 11px var(--sans);transition:.15s}
.budget-mode:hover{border-color:rgba(216,242,107,.35)}
.budget-mode.active{background:var(--lime);border-color:var(--lime);color:#121708}
.market-list{display:flex;flex-direction:column;gap:6px;margin-top:8px}
.market-row{display:flex;align-items:center;gap:10px;background:rgba(8,10,6,.48);border:1px solid var(--line);border-radius:12px;padding:7px 8px;min-width:0}
.market-row img{width:52px;height:52px;border-radius:9px;object-fit:cover;flex-shrink:0;border:1px solid var(--line)}
.market-copy{flex:1;min-width:0}
.market-copy b{display:block;font:700 11px var(--sans);color:#d6dfc9;line-height:1.3}
.market-copy a{display:inline-block;font:600 9.5px var(--sans);color:var(--lime);margin-top:3px}
.market-copy a:hover{text-decoration:underline}
.market-copy small{display:block;font:400 8px var(--mono);color:#6d7760;margin-top:2px;overflow-wrap:anywhere}
.market-price{display:flex;align-items:center;gap:5px;flex-shrink:0}
.market-price span{font:500 8px var(--mono);color:#77806a}
.market-price input{width:96px;height:36px;background:#0a0e07;border:1px solid var(--line);border-radius:9px;color:var(--cream);font:600 11px var(--sans);padding:0 8px;outline:0}
.market-price input:focus{border-color:rgba(216,242,107,.45)}
.market-foot{display:flex;align-items:center;justify-content:space-between;gap:10px;border-top:1px solid var(--line);margin-top:9px;padding-top:8px;font-size:10px;color:#8b947e}
.market-foot b{font:400 16px var(--display);color:var(--cream)}
@media(max-width:700px){
  .market-row{flex-wrap:wrap}
  .market-price{margin-left:auto}
}
EOF
