if (sort === 'diploma') list.sort((a, b) => a.diploma.localeCompare(b.diploma, 'es') || a.title.localeCompare(b.title, 'es'));
if (sort === 'title') list.sort((a, b) => a.title.localeCompare(b.title, 'es'));
