function runFullSimulation() {
  const cfg = simConfigFromUI();
  app.sim = cfg;
  persist();
  const seedOffsets = [11, 29, 47, 73, 101];
  simScenarios = seedOffsets.map(offset => simulateFull(cfg, offset))
