.sim-results-head h2{font:400 22px/1.05 var(--display);letter-spacing:-.025em;color:var(--cream);margin:2px 0 0}
.sim-result-stats{display:flex;gap:6px;flex-wrap:wrap}
.sim-scenario-compare{padding:10px 0 12px;border-top:1px solid rgba(235,241,214,.08);border-bottom:1px solid rgba(235,241,214,.08);margin:8px 0 12px}
.sim-scenarios-head{display:flex;align-items:end;justify-content:space-between;gap:16px;margin-bottom:9px}
.sim-scenarios-head h3{font:400 17px/1.1 var(--display);color:#e6ebd9;margin:3px 0 0}
.sim-scenarios-head p{font-size:9px;line-height:1.45;color:#89927c;max-width:440px;margin:0}
.sim-scenario-grid{display:grid;grid-template-columns:repeat(5,minmax(0,1fr));gap:7px}
.sim-scenario-card{min-width:0;text-align:left;background:rgba(8,10,6,.46);border:1px solid var(--line);border-radius:10px;padding:9px;cursor:pointer;color:inherit;transition:border-color .15s,background .15s,transform .15s}
.sim-scenario-card:hover{border-color:rgba(216,242,107,.4);transform:translateY(-1px)}
.sim-scenario-card.active{background:rgba(216,242,107,.08);border-color:rgba(216,242,107,.65);box-shadow:inset 0 0 0 1px rgba(216,242,107,.12)}
.sim-scenario-rank{display:block;font:500 7.5px var(--mono);letter-spacing:.04em;text-transform:uppercase;color:#9da78f;margin-bottom:7px}
.sim-scenario-card>b{display:block;font:400 20px/1 var(--display);color:#eef0dd}
.sim-scenario-card>b small{font:400 10px var(--mono);color:#9ba68b}
.sim-scenario-meta{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font:400 8px/1.4 var(--mono);color:#88927a;margin-top:4px}
.sim-scenario-card.active .sim-scenario-rank{color:var(--lime)}

