813:     const days = cfg.days;
814:     const baseYieldPerPlant = st.yield || 85;
815:     const cycleFactor = Math.max(.7, Math.min(1.15, cfg.days / (st.flower + 5)));
816:     const lightFactor = Math.max(.78, Math.min(1.12, cfg.light / 18));
817:     const tempPenalty = Math.max(0, Math.abs(cfg.temp - 24) - 2) * 1.1;
818:     const rand = seededRandom((cfg.strainId.charCodeAt(0) || 7) * 131 + days * 17 + cfg.plants * 911 + (cfg.strategy === 'balanced' ? 7 : cfg.strategy.length * 31) + seedOffset);
819:     const growth = [], healthS = [], moistureS = [], nutritionS = [], yieldS = [];
