829:       let stress = 0;
830:       if (moisture < 22 || moisture > 84) stress += 5;
831:       if (nutrition < 18) stress += 4;
832:       if (tempPenalty > 2) stress += Math.min(4, tempPenalty / 2);
833:       if (strat.stress && d % (strat.stressEvery || 3) === 0) stress += strat.stress;
834:       health = Math.max(15, Math.min(99, health + (stress ? -stress : 1.1)));
