845:     const yieldScore = potential ? Math.min(100, Math.round(yieldG / potential * 100)) : 0;
846:     const avgHealth = Math.round(healthS.reduce((a, b) => a + b, 0) / healthS.length);
847:     const healthScore = Math.max(0, Math.min(100, Math.round(avgHealth)));
848:     const stability = Math.max(0, Math.min(100, 100 - stressDays * 2.2 - tempPenalty * 3));
849:     const spentDaily = 4500 * (cfg.light / 18) + (strat.premium > 0 ? 1600 : strat.premium < 0 ? -250 : 650);
