854:     const grade = gradeFor(score);
855:     const activities = [
856:       { day: 1, phase: 'Siembra', title: 'Germinación y siembra', detail: `Hidratar sustrato, ${cfg.light} h luz, ${cfg.temp} °C media.`, done: true },
