import json, urllib.request, socket, base64, os, struct, time, urllib.parse

def http(url, method='GET'):
    req=urllib.request.Request(url,method=method)
    return json.loads(urllib.request.urlopen(req,timeout=3).read())

target=http('http://localhost:9222/json/new?http://localhost:8765/','PUT')
s=socket.create_connection(('127.0.0.1', urllib.parse.urlparse(target['webSocketDebuggerUrl']).port))
key=base64.b64encode(os.urandom(16)).decode()
path=urllib.parse.urlparse(target['webSocketDebuggerUrl']).path
s.sendall((f'GET {path} HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n').encode())
buf=b''
while b'\r\n\r\n' not in buf: buf+=s.recv(4096)
header,buf=buf.split(b'\r\n\r\n',1)
assert b'101' in header,header
n=0
def recvframe():
 global buf
 while len(buf)<2: buf+=s.recv(65536)
 b1,b2=buf[0],buf[1]; ln=b2&127; pos=2
 if ln==126:
  while len(buf)<4: buf+=s.recv(65536)
  ln=struct.unpack('!H',buf[2:4])[0];pos=4
 elif ln==127:
  while len(buf)<10: buf+=s.recv(65536)
  ln=struct.unpack('!Q',buf[2:10])[0];pos=10
 mask=bool(b2&128)
 if mask:
  while len(buf)<pos+4+ln: buf+=s.recv(65536)
  key=buf[pos:pos+4];pos+=4
 else:
  while len(buf)<pos+ln: buf+=s.recv(65536)
 payload=buf[pos:pos+ln];buf=buf[pos+ln:]
 if mask: payload=bytes(c^key[i%4] for i,c in enumerate(payload))
 return b1&15,payload

def send(obj):
 data=json.dumps(obj).encode(); m=os.urandom(4); ln=len(data)
 head=bytes([0x81,0x80|(ln if ln<126 else 126)])+(struct.pack('!H',ln) if 126<=ln<65536 else b'')
 s.sendall(head+m+bytes(c^m[i%4] for i,c in enumerate(data)))
def call(method,params={}):
 global n
 n+=1; my=n; send({'id':my,'method':method,'params':params})
 while True:
  op,p=recvframe()
  if op==8: raise Exception('closed')
  if op==9: s.sendall(b'\x8a\x00');continue
  msg=json.loads(p)
  if msg.get('id')==my:
   if 'error' in msg: raise Exception(msg['error'])
   return msg.get('result',{})

def ev(expr):
 r=call('Runtime.evaluate',{'expression':expr,'returnByValue':True,'awaitPromise':True})
 return r.get('result',{}).get('value',r)
call('Page.enable');call('Runtime.enable')
call('Page.navigate',{'url':'http://localhost:8765/'})
time.sleep(3)
# run simulation by real user-facing event handler
print('before',ev("({title:document.title, errors:document.querySelectorAll('.error').length, sim:!!document.querySelector('#simulateBtn'), view:[...document.querySelectorAll('.view')].filter(x=>x.classList.contains('active')).map(x=>x.id)})"))
# show sim section via nav state then click
print('nav',ev("[...document.querySelectorAll('[data-nav]')].map(x=>[x.dataset.nav,x.textContent.trim()]).slice(0,20)"))
ev("document.querySelector('[data-nav=sim]')?.click()")
ev("document.querySelector('#simulateBtn').click()")
time.sleep(1)
print('desktop',ev("({active:[...document.querySelectorAll('.view')].filter(x=>x.classList.contains('active')).map(x=>x.id),cards:[...document.querySelectorAll('#simScenarioCompare [data-scenario]')].map(x=>({label:x.querySelector('.sim-scenario-rank')?.textContent.trim(),yield:x.querySelector('b')?.innerText.trim(),active:x.getAttribute('aria-pressed')})),title:document.querySelector('#simResultTitle')?.textContent, chart:document.querySelector('#simChartWrap svg polyline')?.getAttribute('points')?.slice(-60), activities:document.querySelectorAll('#simProcess li').length,last:document.querySelector('#simProcess li:last-child')?.innerText.trim()})"))
# select each scenario, verify every selection updates stats and UI
print('all selections',ev("(()=>[...document.querySelectorAll('#simScenarioCompare [data-scenario]')].map(b=>{b.click();return {rank:b.innerText.split('\\n')[0],pressed:b.getAttribute('aria-pressed'),title:document.querySelector('#simResultTitle').textContent,stats:document.querySelector('#simResultStats').innerText.split('\\n').slice(0,2).join(' | '),chart:document.querySelector('#simChartWrap svg polyline')?.getAttribute('points')?.slice(-30),harvest:document.querySelector('#simProcess li:nth-last-child(2)')?.innerText.split('\\n')[2]}}))()"))
# responsive check at mobile viewport
call('Emulation.setDeviceMetricsOverride',{'width':390,'height':844,'deviceScaleFactor':1,'mobile':True})
print('mobile',ev("({width:document.documentElement.clientWidth,scroll:document.documentElement.scrollWidth,grid:getComputedStyle(document.querySelector('.sim-scenario-grid')).gridTemplateColumns,cardWidth:document.querySelector('.sim-scenario-card')?.getBoundingClientRect().width,container:document.querySelector('.sim-results')?.getBoundingClientRect().width})"))
