def http(url, method='GET'):
    return json.loads(urllib.request.urlopen(urllib.request.Request(url,method=method),timeout=4).read())
target=http('http://localhost:9222/json/new?http://localhost:8765/?pdf-test=clean','PUT')
s=socket.create_connection(('127.0.0.1', urllib.parse.urlparse(target['webSocketDebuggerUrl']).port)); s.settimeout(10)
key=base64.b64encode(os.urandom(16)).decode(); path=urllib.parse.urlparse(target['webSocketDebuggerUrl']).path
s.sendall((f'GET {path} HTTP/1.1\r\nHost: localhost\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {key}\r\nSec-WebSocket-Version: 13\r\n\r\n').encode()); buf=b''
