.reading-path-row button{height:28px;padding:0 10px;font-size:9px}
.reading-path-form{margin:10px 0;padding:12px;border:1px solid rgba(216,242,107,.24);border-radius:10px;background:rgba(8,10,6,.5)}
.reading-path-form label{display:block;margin-bottom:6px;color:#d6dfc9;font:600 10px var(--sans)}
.reading-path-form>div{display:flex;align-items:center;gap:7px;flex-wrap:wrap}
.reading-path-form input{flex:1;min-width:170px;height:36px;padding:0 10px;border:1px solid var(--line);border-radius:7px;background:#11160e;color:var(--cream);font:10px var(--sans)}
.reading-path-form small{display:block;margin-top:7px;color:#89927c;font:8px/1.5 var(--mono)}
.rd-dup{margin:10px 0;padding:10px;border:1px solid var(--line);border-radius:8px;background:rgba(8,10,6,.45)}
.rd-dup summary{cursor:pointer;color:#d6dfc9;font:600 10px var(--sans)}
.rd-dup>p{color:#929a86;font:9px/1.5 var(--sans)}
.rd-compare{display:grid;grid-template-columns:repeat(auto-fit,minmax(170px,1fr));gap:8px}
.rd-compare article{min-width:0;padding:9px;border:1px solid var(--line);border-radius:7px}
.rd-compare article>b,.rd-compare article>small,.rd-compare article>code{display:block;overflow-wrap:anywhere}
.rd-compare article>b{color:var(--cream);font-size:10px}
.rd-compare article>small,.rd-compare article>code{margin-top:5px;color:#9da68e;font:8px/1.5 var(--mono)}
.rd-compare article>p{max-height:150px;overflow:auto;color:#c3cbb6;font:9px/1.55 var(--sans)}
@media(max-width:700px){.reading-path-form>div{align-items:stretch}.reading-path-form input{flex-basis:100%}.rd-compare{grid-template-columns:1fr}}

